--
-- Name: notify_macro_update(); Type: FUNCTION; Schema: public; Owner: nutrix
--

CREATE FUNCTION public.notify_macro_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    uid     INTEGER;
    d       DATE;
    payload JSONB;
BEGIN
    IF TG_OP = 'DELETE' THEN
        uid := OLD.user_id;
        d   := OLD.log_date;
    ELSE
        uid := NEW.user_id;
        d   := NEW.log_date;
    END IF;

    SELECT jsonb_build_object(
        'user_id',     uid,
        'date',        d::TEXT,
        'calories',    ROUND(COALESCE(SUM(calories), 0)::numeric, 2),
        'protein_g',   ROUND(COALESCE(SUM(protein), 0)::numeric, 2),
        'carbs_g',     ROUND(COALESCE(SUM(carbs), 0)::numeric, 2),
        'fat_g',       ROUND(COALESCE(SUM(fat), 0)::numeric, 2),
        'meals_count', COUNT(*),
        'latest_item', (SELECT food_name FROM meal_logs
                         WHERE user_id = uid AND log_date = d
                         ORDER BY id DESC LIMIT 1),
        'updated_at',  NOW()::TEXT
    ) INTO payload
    FROM meal_logs
    WHERE user_id = uid AND log_date = d;

    PERFORM pg_notify('macro_update', payload::TEXT);
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.notify_macro_update() OWNER TO nutrix;

